//
//  LoggerExtension.swift
//  VVTerm
//
//  Unified logging utility for the application
//

import Foundation
import os.log

extension Logger {
    /// The app's logging subsystem - must match bundle identifier for proper filtering
    nonisolated private static let appSubsystem = Bundle.main.bundleIdentifier ?? "it.pcad.vvterm"

    /// Create a logger for a specific category
    nonisolated static func forCategory(_ category: String) -> Logger {
        Logger(subsystem: appSubsystem, category: category)
    }

    /// Info-level lifecycle event mirrored into the on-device diagnostics
    /// ring buffer, which survives logd buffer purges under memory pressure
    /// (see DiagnosticsRecorder). Use only for non-sensitive narrative
    /// events (stage names, UUIDs, counts, outcomes) — never credentials,
    /// raw hosts, or terminal content.
    func diagInfo(_ category: String, _ message: @autoclosure () -> String) {
        let text = message()
        info("\(text, privacy: .public)")
        DiagnosticsRecorder.shared.record(level: .info, category: category, message: text)
    }

    /// Error-level lifecycle event mirrored into the on-device diagnostics
    /// ring buffer, like `diagInfo` but at error severity. Use for failure
    /// narrative (attempts, exec/channel failures). The message must already
    /// be sanitized (see `SSHError.diagnosticsMessage`) — never credentials,
    /// raw hosts, or terminal content.
    func diagError(_ category: String, _ message: @autoclosure () -> String) {
